import 'server-only';
import type { IntegrationEnv } from '../env';
import { AppError } from '../errors';
import { callRows } from './parse';

// Salestrail Pull API (https://www.salestrail.io/knowledge-base/how-to-use-salestrail-pull-api).
// Basic auth with the username/password generated by the owner at
// callanalytics.salestrail.io/integration/apidocs. Data scope follows that user's dashboard access,
// so the credentials must belong to the organisation OWNER to see everyone's calls.
const BASE = 'https://standalone-api.salestrail.io';

function auth(cfg: IntegrationEnv) {
  return `Basic ${btoa(`${cfg.SALESTRAIL_API_USERNAME}:${cfg.SALESTRAIL_API_PASSWORD}`)}`;
}

/** Calls created (uploaded to Salestrail) between `from` and `to`. */
export async function fetchCallsCreatedBetween(cfg: IntegrationEnv, from: Date, to: Date) {
  const qs = new URLSearchParams({ from: from.toISOString(), to: to.toISOString() });
  const res = await fetch(`${BASE}/export/calls/byCreated/json?${qs}`, {
    headers: { Authorization: auth(cfg), Accept: 'application/json' },
  });
  if (res.status === 401 || res.status === 403) throw new AppError('NOT_CONFIGURED', 'Salestrail rejected the API username/password');
  if (!res.ok) throw new AppError('INTERNAL', `Salestrail call list failed (${res.status})`);
  return callRows(await res.json());
}

/**
 * Short-lived download URL for a call's recording, or null if it has none (yet).
 * Salestrail answers 302 with the blob URL in Location, or 404 when there is no recording.
 */
export async function recordingUrl(cfg: IntegrationEnv, callId: string): Promise<string | null> {
  const res = await fetch(`${BASE}/export/calls/${encodeURIComponent(callId)}/recording`, {
    headers: { Authorization: auth(cfg) }, redirect: 'manual',
  });
  if (res.status === 404) return null;
  const location = res.headers.get('location');
  if (res.status >= 300 && res.status < 400 && location) return location;
  if (res.status === 401 || res.status === 403) throw new AppError('NOT_CONFIGURED', 'Salestrail rejected the API username/password');
  throw new AppError('INTERNAL', `Salestrail recording lookup failed (${res.status})`);
}
